<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import InventorySubnav from '../components/InventorySubnav.vue'; import InventoryScenarioBar from '../components/InventoryScenarioBar.vue'
import { useInventoryStore } from '../runtime/inventory-store'; import type { InventoryStatus } from '../types'; import './inventory-views.css'
const store=useInventoryStore(); const route=useRoute(); const router=useRouter(); const {workspace,loading,error,isEmpty,scenario,actor,canWrite}=storeToRefs(store); const selected=ref<string[]>([])
const filters=reactive({warehouseId:String(route.query.warehouseId??''),status:String(route.query.status??''),keyword:String(route.query.keyword??'')})
const statusLabel={normal:'正常',insufficient:'库存不足',zero:'零库存',overstock:'超储',unavailable:'数据源未接入'} as const
const allSelected=computed(()=>workspace.value.stocks.items.length>0&&workspace.value.stocks.items.every(row=>selected.value.includes(`${row.warehouse.id}:${row.skuId}`)))
function quantity(milli:number|null,unit=''){return milli===null?'数据源未接入':`${(milli/1000).toLocaleString('zh-CN',{maximumFractionDigits:3})}${unit}`}
function money(cents:number|null){return cents===null?'—':`¥${(cents/100).toFixed(2)}`}
async function search(){const query={warehouseId:filters.warehouseId||undefined,status:(filters.status||undefined) as InventoryStatus|undefined,keyword:filters.keyword||undefined,page:1,pageSize:30 as const}; await router.replace({query:Object.fromEntries(Object.entries(query).filter(([,v])=>v!==undefined).map(([k,v])=>[k,String(v)]))}); selected.value=[]; await store.applyQuery(query)}
async function reset(){Object.assign(filters,{warehouseId:'',status:'',keyword:''});await router.replace({query:{}});await store.applyQuery({page:1,pageSize:30})}
function toggle(key:string){selected.value=selected.value.includes(key)?selected.value.filter(x=>x!==key):[...selected.value,key]}
function toggleAll(){const keys=workspace.value.stocks.items.map(row=>`${row.warehouse.id}:${row.skuId}`);selected.value=allSelected.value?selected.value.filter(x=>!keys.includes(x)):[...new Set([...selected.value,...keys])]}
function download(){const blob=new Blob([store.exportStocks(selected.value)],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='inventory-stocks.csv';a.click();URL.revokeObjectURL(url)}
onMounted(()=>store.load())
</script>
<template><section class="inventory-page"><header class="inventory-header"><div><h1>库存列表</h1><p>仓库 × SKU 账面库存；订单待出库与采购在途未接入时不以 0 冒充。</p></div><InventoryScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><InventorySubnav/><form class="inventory-panel inventory-filter" @submit.prevent="search"><label>仓库<select v-model="filters.warehouseId"><option value="">全部仓库</option><option v-for="item in workspace.warehouses" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>库存状态<select v-model="filters.status"><option value="">全部状态</option><option v-for="(label,key) in statusLabel" :key="key" :value="key">{{label}}</option></select></label><label class="keyword">商品关键词<input v-model="filters.keyword" type="search" placeholder="SKU / 商品名称 / 条码"></label><button class="inv-button" type="button" @click="reset">重置</button><button class="inv-button primary" type="submit">查询</button></form><p v-if="!workspace.catalogAvailable&&!error" class="inventory-warning">商品资料服务加载失败；库存标识和数量仍保留，商品名称显示“资料不可用”。</p><div v-if="error" class="inventory-state error" role="alert"><strong>库存数据加载失败</strong><p>{{error}}</p><button class="inv-button" @click="store.load">重试</button></div><div v-else-if="loading" class="inventory-state"><strong>正在加载库存数据…</strong></div><div v-else-if="isEmpty" class="inventory-state"><strong>暂无库存数据</strong><p>当前筛选或模拟场景没有余额。</p></div><template v-else><div class="inventory-toolbar"><strong>共 {{workspace.stocks.total}} 条</strong><div><button class="inv-button" @click="store.load">刷新</button><button v-if="canWrite" class="inv-button" @click="download">导出 CSV</button></div></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th><input type="checkbox" :checked="allSelected" aria-label="选择当前页" @change="toggleAll"></th><th>仓库</th><th>商品 / 规格</th><th>SKU / 条码</th><th class="quantity">期初</th><th class="quantity">当前</th><th class="quantity">待出库</th><th class="quantity">可用</th><th class="quantity">在途</th><th class="quantity">安全库存</th><th>状态</th><th class="money">成本单价</th><th class="money">库存金额</th><th>操作</th></tr></thead><tbody><tr v-for="row in workspace.stocks.items" :key="`${row.warehouse.id}:${row.skuId}`"><td><input type="checkbox" :checked="selected.includes(`${row.warehouse.id}:${row.skuId}`)" @change="toggle(`${row.warehouse.id}:${row.skuId}`)"></td><td><strong>{{row.warehouse.name}}</strong><small>{{row.warehouse.code}}{{row.warehouse.saleProhibited?' · 禁售':''}}</small></td><td><RouterLink :to="`/inventory/stocks/${row.warehouse.id}/${row.skuId}`"><strong>{{row.sku?.productName??'商品资料不可用'}}</strong></RouterLink><small>{{row.sku?.specification??row.skuId}}</small></td><td>{{row.sku?.skuCode??row.skuId}}<small>{{row.sku?.barcode??'—'}}</small></td><td class="quantity">{{quantity(row.openingMilli,row.sku?.baseUnitName)}}</td><td class="quantity">{{quantity(row.currentMilli,row.sku?.baseUnitName)}}</td><td class="quantity">{{quantity(row.pendingOutboundMilli)}}</td><td class="quantity">{{quantity(row.availableMilli)}}</td><td class="quantity">{{quantity(row.inTransitMilli)}}</td><td class="quantity">{{quantity(row.safetyMinimumMilli,row.sku?.baseUnitName)}}</td><td><span class="inv-status" :class="`inv-status-${row.status}`">{{statusLabel[row.status]}}</span></td><td class="money">{{money(row.costPerBaseUnitCents)}}</td><td class="money">{{money(row.amountCents)}}</td><td><RouterLink :to="`/inventory/stocks/${row.warehouse.id}/${row.skuId}`">详情</RouterLink></td></tr></tbody></table></div><footer class="inventory-pagination"><span>第 {{workspace.stocks.page}} 页</span><button class="inv-button" :disabled="workspace.stocks.page<=1" @click="store.applyQuery({...store.query,page:workspace.stocks.page-1})">上一页</button><button class="inv-button" :disabled="workspace.stocks.page*30>=workspace.stocks.total" @click="store.applyQuery({...store.query,page:workspace.stocks.page+1})">下一页</button></footer></template></section></template>
